struct KadrioBottomSheet<Sheet: View>: UIViewControllerRepresentable {
    @Binding var isPresented: Bool
    let height: CGFloat
    var onDismiss: () -> Void = {}
    @ViewBuilder var sheet: () -> Sheet

    func makeCoordinator() -> Coordinator { Coordinator(parent: self) }

